import { describe, expect, it } from 'vitest';

import { formatEnvFile, isGeneratedEnvFile } from './envfile.mjs';

describe('isGeneratedEnvFile', () => {
  it('accepts the header this package writes', () => {
    expect(isGeneratedEnvFile(formatEnvFile({ KEY: 'v' }))).toBe(true);
  });

  it('accepts the header a predecessor tool wrote', () => {
    expect(
      isGeneratedEnvFile(
        '# Generated by `pnpm secrets:materialize` — do not edit.\nKEY="v"\n',
      ),
    ).toBe(true);
  });

  it('rejects a generated header from an unrelated command', () => {
    expect(
      isGeneratedEnvFile(
        '# Generated by `something-else` — do not edit.\nKEY="v"\n',
      ),
    ).toBe(false);
  });

  it('rejects a file that starts with a plain assignment', () => {
    expect(isGeneratedEnvFile('KEY="v"\n')).toBe(false);
  });

  it('accepts a header ending in CRLF', () => {
    expect(
      isGeneratedEnvFile(
        '# Generated by `pnpm secrets:materialize` — do not edit.\r\nKEY="v"\r\n',
      ),
    ).toBe(true);
  });
});
